      backup_text =
        "# TIC-TAC-TOE #\n\
         # Classic 3x3 game with cats vs dogs #\n\n\
         type Cell = + Empty + X + O in\n\n\
         type Board = [Cell] in  # 9 cells, row-major: [0,1,2,3,4,5,6,7,8] #\n\n\
         type Player = + PlayerX + PlayerO in\n\n\
         type GameStatus =\n\
         + InProgress\n\
         + Won(Player)\n\
         + Draw\n\
         in\n\n\
         type Model = (\n\
         board = Board,\n\
         turn = Player,\n\
         status = GameStatus\n\
         ) in\n\n\
         # Initial empty board #\n\
         let emptyBoard : Board =\n\
         [Empty, Empty, Empty,\n\
         Empty, Empty, Empty,\n\
         Empty, Empty, Empty]\n\
         in\n\n\
         let init : Model = (\n\
         board = emptyBoard,\n\
         turn = PlayerX,\n\
         status = InProgress\n\
         ) in\n\n\
         # Get cell at position (0-8) #\n\
         let getCell : (Board, Int) -> Cell =\n\
         fun (board, pos) ->\n\
         nth(board, pos)\n\
         in\n\n\
         # Set cell at position #\n\
         let setCell : (Board, Int, Cell) -> Board =\n\
         fun (board, pos, cell) ->\n\
         mapi(board, fun (i, c) -> if i == pos then cell else c)\n\
         in\n\n\
         # Convert player to their cell marker #\n\
         let playerCell : Player -> Cell =\n\
         fun p ->\n\
         case p\n\
         | PlayerX => X\n\
         | PlayerO => O\n\
         end\n\
         in\n\n\
         # Check if three cells are the same and not empty #\n\
         let threeInRow : (Cell, Cell, Cell) -> Option =\n\
         fun (a, b, c) ->\n\
         case (a, b, c)\n\
         | (X, X, X) => Some(X)\n\
         | (O, O, O) => Some(O)\n\
         | _ => None\n\
         end\n\
         in\n\n\
         # Get cells at positions #\n\
         let getCells3 : (Board, Int, Int, Int) -> (Cell, Cell, Cell) =\n\
         fun (board, i, j, k) ->\n\
         (getCell(board, i), getCell(board, j), getCell(board, k))\n\
         in\n\n\
         # Check all winning lines #\n\
         let checkWinner : Board -> Option =\n\
         fun board ->\n\
         # Rows #\n\
         let row0 = threeInRow(getCells3(board, 0, 1, 2)) in\n\
         let row1 = threeInRow(getCells3(board, 3, 4, 5)) in\n\
         let row2 = threeInRow(getCells3(board, 6, 7, 8)) in\n\
         # Columns #\n\
         let col0 = threeInRow(getCells3(board, 0, 3, 6)) in\n\
         let col1 = threeInRow(getCells3(board, 1, 4, 7)) in\n\
         let col2 = threeInRow(getCells3(board, 2, 5, 8)) in\n\
         # Diagonals #\n\
         let diag1 = threeInRow(getCells3(board, 0, 4, 8)) in\n\
         let diag2 = threeInRow(getCells3(board, 2, 4, 6)) in\n\
         # Return first winning line found #\n\
         case row0 | Some(c) => Some(c) | None =>\n\
         case row1 | Some(c) => Some(c) | None =>\n\
         case row2 | Some(c) => Some(c) | None =>\n\
         case col0 | Some(c) => Some(c) | None =>\n\
         case col1 | Some(c) => Some(c) | None =>\n\
         case col2 | Some(c) => Some(c) | None =>\n\
         case diag1 | Some(c) => Some(c) | None =>\n\
         diag2\n\
         end end end end end end end\n\
         in\n\n\
         # Check if board is full #\n\
         let isFull : Board -> Bool =\n\
         fun board ->\n\
         for_all(board, fun c -> c != Empty)\n\
         in\n\n\
         # Convert winning cell to player #\n\
         let cellToPlayer : Cell -> Player =\n\
         fun c ->\n\
         case c\n\
         | X => PlayerX\n\
         | O => PlayerO\n\
         | Empty => PlayerX  # shouldn't happen #\n\
         end\n\
         in\n\n\
         # Determine game status from board #\n\
         let calcStatus : Board -> GameStatus =\n\
         fun board ->\n\
         case checkWinner(board)\n\
         | Some(c) => Won(cellToPlayer(c))\n\
         | None =>\n\
         if isFull(board) then Draw\n\
         else InProgress\n\
         end\n\
         in\n\n\
         # Switch turns #\n\
         let nextPlayer : Player -> Player =\n\
         fun p ->\n\
         case p\n\
         | PlayerX => PlayerO\n\
         | PlayerO => PlayerX\n\
         end\n\
         in\n\n\
         # Check if move is valid #\n\
         let isValidMove : (Model, Int) -> Bool =\n\
         fun (m, pos) ->\n\
         pos >= 0 && pos < 9 &&\n\
         getCell(m.board, pos) == Empty &&\n\
         m.status == InProgress\n\
         in\n\n\
         # Make a move #\n\
         let move : (Model, Int) -> Model =\n\
         fun (m, pos) ->\n\
         if isValidMove(m, pos) then\n\
         let newBoard = setCell(m.board, pos, playerCell(m.turn)) in\n\
         let newStatus = calcStatus(newBoard) in\n\
         (\n\
         board = newBoard,\n\
         turn = nextPlayer(m.turn),\n\
         status = newStatus\n\
         )\n\
         else m  # Invalid move, no change #\n\
         in\n\n\
         # Play a sequence of moves #\n\
         let play : (Model, [Int]) -> Model =\n\
         fun (model, moves) ->\n\
         fold_left(moves, move, model)\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         hint \"initial board is empty\"\n\
         test\n\
         for_all(init.board, fun c -> c == Empty)\n\
         end;\n\n\
         hint \"X plays first\"\n\
         test\n\
         init.turn == PlayerX\n\
         end;\n\n\
         hint \"game starts in progress\"\n\
         test\n\
         init.status == InProgress\n\
         end;\n\n\
         hint \"move places correct marker\"\n\
         test\n\
         let m = move(init, 0) in\n\
         getCell(m.board, 0) == X\n\
         end;\n\n\
         hint \"turn alternates after move\"\n\
         test\n\
         let m = move(init, 0) in\n\
         m.turn == PlayerO\n\
         end;\n\n\
         hint \"O places O marker\"\n\
         test\n\
         let m = play(init, [0, 4]) in\n\
         getCell(m.board, 4) == O\n\
         end;\n\n\
         hint \"invalid move on occupied cell\"\n\
         test\n\
         let m = play(init, [0, 0]) in  # X plays 0, O tries 0 #\n\
         getCell(m.board, 0) == X &&    # Still X, not O #\n\
         m.turn == PlayerO              # Still O's turn #\n\
         end;\n\n\
         hint \"X wins with top row\"\n\
         test\n\
         let m = play(init, [0, 3, 1, 4, 2]) in  # X: 0,1,2 O: 3,4 #\n\
         m.status == Won(PlayerX)\n\
         end;\n\n\
         hint \"O wins with middle column\"\n\
         test\n\
         let m = play(init, [0, 1, 2, 4, 6, 7]) in  # X: 0,2,6 O: 1,4,7 #\n\
         m.status == Won(PlayerO)\n\
         end;\n\n\
         hint \"X wins with main diagonal\"\n\
         test\n\
         let m = play(init, [0, 1, 4, 2, 8]) in  # X: 0,4,8 O: 1,2 #\n\
         m.status == Won(PlayerX)\n\
         end;\n\n\
         hint \"X wins with anti-diagonal\"\n\
         test\n\
         let m = play(init, [2, 0, 4, 1, 6]) in  # X: 2,4,6 O: 0,1 #\n\
         m.status == Won(PlayerX)\n\
         end;\n\n\
         hint \"draw when board full with no winner\"\n\
         test\n\
         let m = play(init, [0, 1, 2, 5, 3, 6, 4, 8, 7]) in\n\
         case m.status | Draw => true | _ => false end\n\
         end;\n\n\
         hint \"no moves after win\"\n\
         test\n\
         let m = play(init, [0, 3, 1, 4, 2, 5]) in\n\
         case m.status | Won(PlayerX) => getCell(m.board, 5) == Empty | _ => \
         false end\n\
         end;\n\n\
         hint \"can't move to position 9 or higher\"\n\
         test\n\
         let m = move(init, 9) in\n\
         for_all(m.board, fun c -> c == Empty)\n\
         end;\n\n\
         hint \"can't move to negative position\"\n\
         test\n\
         let m = move(init, -1) in\n\
         for_all(m.board, fun c -> c == Empty)\n\
         end;\n\n\
         hint \"O wins with bottom row\"\n\
         test\n\
         let m = play(init, [0, 6, 1, 7, 4, 8]) in  # X: 0,1,4 O: 6,7,8 #\n\
         m.status == Won(PlayerO)\n\
         end;\n\n\
         hint \"X wins with left column\"\n\
         test\n\
         let m = play(init, [0, 1, 3, 4, 6]) in  # X: 0,3,6 O: 1,4 #\n\
         m.status == Won(PlayerX)\n\
         end;\n\n\
         hint \"X wins with right column\"\n\
         test\n\
         let m = play(init, [2, 0, 5, 1, 8]) in  # X: 2,5,8 O: 0,1 #\n\
         m.status == Won(PlayerX)\n\
         end;\n\n\
         # Demo: a quick game #\n\
         play(init, [4, 0, 2, 6, 1, 3, 7])\n";
      refractors = "()";
    } )
